const COOKIE='collector_session';
const MAX_BYTES=5*1024*1024;
function json(body,status=200){return new Response(JSON.stringify(body),{status,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store'}});}
function cookie(request,name){for(const p of (request.headers.get('Cookie')||'').split(';')){const s=p.trim();if(s.startsWith(name+'='))return s.slice(name.length+1);}return '';}
function b64(bytes){return btoa(String.fromCharCode(...new Uint8Array(bytes))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}
async function sha256(value){return b64(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value)));}
const SHOP_TIERS=new Set(['collector_plus','vendor','vendor_plus','organizer','organizer_plus','event_organizer','event_organizer_plus','vip','lifetime','lifetime_vip']);
function normalizeTier(value){return String(value||'').trim().toLowerCase().replace(/\+/g,'_plus').replace(/[\s-]+/g,'_');}
async function auth(request,env){const token=cookie(request,COOKIE);if(!token)return null;const a=await env.DB.prepare('SELECT id,session_expires_at,is_admin,membership_tier,membership_entitlement_tier,membership_status FROM accounts WHERE session_token_hash=? LIMIT 1').bind(await sha256(token)).first();if(!a||!a.session_expires_at||Number(a.session_expires_at)<=Date.now())return null;const allowed=Number(a.is_admin)===1||(['active','trialing'].includes(String(a.membership_status||'').toLowerCase())&&[a.membership_entitlement_tier,a.membership_tier].some(tier=>SHOP_TIERS.has(normalizeTier(tier))));return allowed?a:null;}
export async function onRequestPost({request,env}){try{if(!env.DB)return json({ok:false,error:'database_not_configured'},500);if(!env.VENDOR_MEDIA)return json({ok:false,error:'image_storage_not_configured'},503);const a=await auth(request,env);if(!a)return json({ok:false,error:'shop_membership_required'},403);const type=(request.headers.get('content-type')||'').toLowerCase();const ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp','image/avif':'avif'}[type];if(!ext)return json({ok:false,error:'unsupported_image_type'},415);const length=Number(request.headers.get('content-length')||0);if(length>MAX_BYTES)return json({ok:false,error:'image_too_large'},413);const data=await request.arrayBuffer();if(!data.byteLength||data.byteLength>MAX_BYTES)return json({ok:false,error:'image_too_large_or_empty'},413);const key='vendors/'+a.id+'/'+crypto.randomUUID()+'.'+ext;await env.VENDOR_MEDIA.put(key,data,{httpMetadata:{contentType:type,cacheControl:'public, max-age=31536000, immutable'}});return json({ok:true,key,url:'/api/vendor/image?key='+encodeURIComponent(key)} ,201);}catch(e){console.error('Vendor image upload failed',e);return json({ok:false,error:'image_upload_failed'},500);}}
export async function onRequest(){return json({ok:false,error:'method_not_allowed'},405);}
